mkdir -p /tmp/fakekms && cat > /tmp/fakekms/fakekms.py <<'EOF'
"""In-memory fake KMS provider for testing."""
import os, base64, uuid

STORE = {}
DELETED = []

class FakeProvider:
    provider_id = "fake-hsm"
    capabilities = {
        "algorithms": ["AES256", "RSA2048"],
        "operations": ["generate", "rotate", "import_material", "export_material", "delete"],
    }
    def generate(self, algorithm):
        return self._mint(algorithm, None)
    def rotate(self, algorithm):
        return self._mint(algorithm, None)
    def _mint(self, algorithm, public_key):
        from keymgr.crypto import generate_key
        g = generate_key(algorithm)
        handle = "h-" + uuid.uuid4().hex
        enc = base64.b64encode(g.private_material.encode()).decode()
        STORE[handle] = (g.public_material, enc)
        return {"handle": handle, "public_key": g.public_material, "encrypted_material": enc}
    def import_material(self, algorithm, public_key, material):
        handle = "h-" + uuid.uuid4().hex
        STORE[handle] = (public_key, material)
        return {"handle": handle, "public_key": public_key, "encrypted_material": material}
    def export_material(self, handle):
        pk, enc = STORE[handle]
        return {"public_key": pk, "encrypted_material": enc}
    def delete(self, handle):
        STORE.pop(handle, None)
        DELETED.append(handle)

def factory():
    return FakeProvider()
